<script setup lang="ts">import QRCode from'qrcode';import{computed,ref,watch}from'vue';import{useRoute}from'vue-router';import{getPublicArticle,publicAttachmentUrl,publicBodyHtml,type PublicArticleDetail}from'../../api/articles';import PublicSiteHeader from'../../components/PublicSiteHeader.vue';import PublicSiteFooter from'../../components/PublicSiteFooter.vue';import{setPageMeta,summarizeHtml}from'../../seo';const route=useRoute(),article=ref<PublicArticleDetail|null>(null),loading=ref(false),error=ref(''),articleUrl=ref(''),qrCodeUrl=ref(''),copyMessage=ref('');const renderedBody=computed(()=>article.value?publicBodyHtml(article.value):'');watch(()=>route.params.id,async v=>{const id=Number(v);article.value=null;error.value='';if(!Number.isInteger(id)||id<=0){error.value='文章不可用或不存在';return}loading.value=true;try{const a=await getPublicArticle(id);article.value=a;articleUrl.value=window.location.origin+`/article/${id}`;qrCodeUrl.value=await QRCode.toDataURL(articleUrl.value,{width:180,margin:1});setPageMeta({title:a.title,description:summarizeHtml(a.bodyHtml,[a.source,a.publishDate].filter(Boolean).join(' · '))})}catch{error.value='文章不可用或不存在'}finally{loading.value=false}},{immediate:true});async function copy(){try{await navigator.clipboard.writeText(articleUrl.value);copyMessage.value='链接已复制'}catch{copyMessage.value='复制失败，请手动复制浏览器地址'}}function size(n:number){if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;return`${(n/1048576).toFixed(1)} MB`}</script><template><PublicSiteHeader/><main class="article-detail site-width"><p v-if="loading" class="public-state">正在加载文章…</p><template v-else-if="article"><nav class="breadcrumb"><router-link to="/">首页</router-link><span>/</span><router-link :to="article.columnAlias?`/column/${article.columnAlias}`:`/columns/${article.columnId}`">{{article.columnName}}</router-link><span>/</span><span>正文</span></nav><header class="article-heading"><h1 data-testid="public-article-title">{{article.title}}</h1><div class="article-meta"><span v-if="article.source">信息来源：{{article.source}}</span><time v-if="article.publishDate">发布时间：{{article.publishDate}}</time></div></header><div class="article-body rich-content" data-testid="public-article-body" v-html="renderedBody"/><section v-if="article.attachments.length" class="article-attachments" data-testid="public-attachments"><h2>附件下载</h2><a v-for="f in article.attachments" :key="f.id" :data-testid="`public-attachment-${f.id}`" :href="publicAttachmentUrl(f.id)"><span>{{f.originalFilename}}</span><small>{{size(f.sizeBytes)}}</small></a></section><section class="article-share"><div><button data-testid="copy-article-link" @click="copy">复制链接</button><p v-if="copyMessage">{{copyMessage}}</p></div><figure v-if="qrCodeUrl"><img data-testid="article-qrcode" :src="qrCodeUrl" alt="当前页面访问二维码"><figcaption>扫码访问当前页面</figcaption></figure></section></template><p v-else class="public-state error-text" data-testid="public-article-unavailable">{{error}}</p></main><PublicSiteFooter/></template>
